<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway;

use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\PlatformIdentity;

class PlatformIdentityCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(PlatformIdentity $platformIdentity, ?int $size): PlatformIdentityCursor
    {
        $next = clone $this;
        $next->sinceUid = $platformIdentity->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
